  vsetvli x15, x11, e8, m1, tu, mu
  LI(x10, 0x00)
SmV_cg_cp_vsetvl_i_avl_eq_zero_vsetvl_avl0:
  vsetvl x15, x11, x10
# cp_vsetvl_i_avl_eq_vlmax
  vsetvli x11, x0, e8, m1, tu, mu  # rs1 = VLMAX
SmV_cg_cp_vsetvl_i_avl_eq_vlmax_vsetvli_avl_eq:
  vsetvli x15, x11, e8, m1, tu, mu
  vsetvli x11, x0, e8, m1, tu, mu  # reload VLMAX
  LI(x10, 0x00)
SmV_cg_cp_vsetvl_i_avl_eq_vlmax_vsetvl_avl_eq:
  vsetvl x15, x11, x10
# cp_vsetvl_i_avl_lt_2x_vlmax
